:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --gold: #f5c542;
  --text: #ffffff;
  --text-muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  color: var(--gold);
  letter-spacing: 1px;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}

.stat {
  font-size: 1.125rem;
  color: var(--text-muted);
}

.stat span {
  color: var(--text);
  font-weight: 700;
}

.coin {
  display: block;
  width: 140px;
  height: 140px;
  margin: 0 auto 24px;
  border: none;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #ffe680, var(--gold) 60%, #b8860b);
  font-size: 4rem;
  line-height: 1;
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.2s ease;
  box-shadow: 0 6px 0 #b8860b, 0 8px 16px rgba(0, 0, 0, 0.3);
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.coin:hover {
  transform: scale(1.05);
  box-shadow: 0 6px 0 #b8860b, 0 10px 20px rgba(0, 0, 0, 0.4);
}

.coin:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

.coin:active {
  transform: scale(0.95);
  box-shadow: 0 2px 0 #b8860b, 0 4px 8px rgba(0, 0, 0, 0.3);
}

.upgrade {
  background: var(--accent);
  color: var(--text);
  border: none;
  border-radius: 12px;
  padding: 16px 24px;
  font-size: 1.125rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease;
  width: 100%;
  max-width: 280px;
  margin: 0 auto;
  display: block;
}

.upgrade:hover {
  background: #ff5c77;
}

.upgrade:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 3px;
}

.upgrade:active {
  transform: scale(0.97);
}

.upgrade:disabled {
  background: #4a4a5a;
  color: var(--text-muted);
  cursor: not-allowed;
  transform: none;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  .coin {
    width: 120px;
    height: 120px;
    font-size: 3.5rem;
  }
  h1 {
    font-size: 1.5rem;
  }
}

let points = 0;
let upgradeCount = 0;
let nextPrice = 10;

const pointsEl = document.getElementById('points');
const upgradeCountEl = document.getElementById('upgrade-count');
const nextPriceEl = document.getElementById('next-price');
const coinButton = document.getElementById('coin-button');
const upgradeButton = document.getElementById('upgrade-button');

function render() {
  pointsEl.textContent = Math.floor(points);
  upgradeCountEl.textContent = upgradeCount;
  nextPriceEl.textContent = nextPrice;
  upgradeButton.disabled = points < nextPrice;
}

coinButton.addEventListener('click', () => {
  points += 1;
  render();
});

upgradeButton.addEventListener('click', () => {
  if (points < nextPrice) return;
  points -= nextPrice;
  upgradeCount += 1;
  nextPrice *= 2;
  render();
});

setInterval(() => {
  if (upgradeCount > 0) {
    points += upgradeCount;
    render();
  }
}, 1000);

render();
